    question: "Difference between null and undefined",
    idealAnswer: "**`null` and `undefined`** are both special types in JavaScript/TypeScript that represent absence of value, but they have different meanings and use cases.\n\n**`undefined`:**\n- Default value of uninitialized variables\n- Function parameters that weren't provided\n- Object properties that don't exist\n- Return value of functions that don't return anything\n\n**`null`:**\n- Explicitly set by developers to indicate \"no value\"\n- Represents intentional absence of any object value\n- Must be assigned explicitly\n\n**Key Differences:**\n```typescript\n// undefined examples\nlet variable;           // undefined\nfunction paramTest(param) { console.log(param); }\nparamTest();           // undefined\nconst obj = {};\nconsole.log(obj.prop); // undefined\n\n// null examples\nlet emptyValue: null = null;        // explicitly null\nconst user = { name: null };        // intentionally no name\nfunction findUser(id: number): User | null {\n  return id === 0 ? null : { id, name: \"John\" }; // explicit null\n}\n```\n\n**Type Checking:**\n```typescript\n// typeof operator\ntypeof undefined; // \"undefined\"\ntypeof null;      // \"object\" (historical JavaScript quirk)\n\n// Equality checks\nundefined == null;   // true (loose equality)\nundefined === null;  // false (strict equality)\n\n// Best practice: strict equality\nif (value === null) {\n  // Handle null case\n}\nif (value === undefined) {\n  // Handle undefined case\n}\n```\n\n**TypeScript Configuration:**\n```typescript\n// tsconfig.json\n{\n  \"compilerOptions\": {\n    \"strictNullChecks\": true  // Enables strict null checking\n  }\n}\n\n// With strictNullChecks: true\nlet name: string = undefined; // Error!\nlet age: number | null = null; // OK\nlet email?: string; // string | undefined\n```\n\n**Practical Examples:**\n```typescript\n// Function parameters\nfunction greet(name?: string) {\n  // name can be undefined\n  if (name === undefined) {\n    console.log(\"Hello, Guest!\");\n  } else {\n    console.log(`Hello, ${name}!`);\n  }\n}\n\ngreet();        // undefined\ngreet(\"John\"); // \"John\"\n\n// Object properties\ninterface User {\n  id: number;\n  name: string;\n  email?: string | null; // optional or null\n}\n\nconst user: User = {\n  id: 1,\n  name: \"John\",\n  email: null // explicitly no email\n};\n\n// Safe property access\nfunction getUserEmail(user: User): string {\n  return user.email ?? \"No email provided\";\n  // Uses nullish coalescing: returns right side if left is null or undefined\n}\n```\n\n**Best Practices:**\n- Use `undefined` for default/uninitialized values\n- Use `null` for intentionally empty values\n- Enable `strictNullChecks` in TypeScript\n- Use optional chaining (`?.`) and nullish coalescing (`??`) operators\n- Be explicit about which you expect in function signatures"
