    question: "What is intersection type?",
    idealAnswer: "**Intersection types** allow you to combine multiple types into one type that has all the features of the constituent types. They're denoted using the ampersand (`&`) operator.\n\n**Basic Syntax:**\n```typescript\ntype IntersectionType = Type1 & Type2 & Type3;\n```\n\n**Simple Intersection Examples:**\n```typescript\ninterface Person {\n  name: string;\n  age: number;\n}\n\ninterface Employee {\n  id: number;\n  department: string;\n}\n\n// Combine both interfaces\ntype PersonEmployee = Person & Employee;\n\nconst worker: PersonEmployee = {\n  name: \"John Doe\",\n  age: 30,\n  id: 12345,\n  department: \"Engineering\"\n};\n```\n\n**Adding Properties to Existing Types:**\n```typescript\ninterface User {\n  id: number;\n  name: string;\n}\n\ntype UserWithTimestamp = User & {\n  createdAt: Date;\n  updatedAt: Date;\n};\n\nfunction createUser(userData: User): UserWithTimestamp {\n  const now = new Date();\n  return {\n    ...userData,\n    createdAt: now,\n    updatedAt: now\n  };\n}\n```\n\n**Intersection with Utility Types:**\n```typescript\ninterface Product {\n  id: number;\n  name: string;\n  price: number;\n}\n\ntype PartialProduct = Partial<Product> & {\n  lastModified: Date;\n};\n\nfunction updateProduct(id: number, updates: PartialProduct): Product {\n  // Implementation\n  return {} as Product;\n}\n```\n\n**Complex Intersection Patterns:**\n```typescript\n// Mixin pattern\ntype Timestamped = {\n  timestamp: Date;\n};\n\ntype Identifiable = {\n  id: string | number;\n};\n\ntype Loggable = {\n  log(): void;\n};\n\ntype EnhancedEntity = Timestamped & Identifiable & Loggable;\n\nclass BaseEntity implements EnhancedEntity {\n  constructor(\n    public id: number,\n    public timestamp: Date = new Date()\n  ) {}\n  \n  log(): void {\n    console.log(`Entity ${this.id} created at ${this.timestamp}`);\n  }\n}\n```\n\n**Function Type Intersection:**\n```typescript\ntype Validator = (value: any) => boolean;\ntype Formatter = (value: any) => string;\ntype Transformer = (value: any) => any;\n\ntype Processor = Validator & Formatter & Transformer;\n\nfunction createProcessor(): Processor {\n  const process = function(value: any): any {\n    // Validation logic\n    if (typeof value !== \"string\") return false;\n    \n    // Transformation logic\n    const transformed = value.toUpperCase();\n    \n    // Formatting logic\n    return `Processed: ${transformed}`;\n  } as Processor;\n  \n  return process;\n}\n\nconst processor = createProcessor();\nconst result = processor(\"hello\"); // Returns \"Processed: HELLO\"\n```\n\n**Intersection with Generics:**\n```typescript\ninterface Repository<T> {\n  findById(id: number): Promise<T | null>;\n  save(entity: T): Promise<T>;\n  delete(id: number): Promise<void>;\n}\n\ninterface Cacheable {\n  cache(): void;\n  invalidate(): void;\n}\n\ntype CachedRepository<T> = Repository<T> & Cacheable;\n\nclass UserRepository implements CachedRepository<User> {\n  private cache = new Map<number, User>();\n  \n  async findById(id: number): Promise<User | null> {\n    // Check cache first\n    if (this.cache.has(id)) {\n      return this.cache.get(id)!;\n    }\n    \n    // Database lookup\n    const user = await this.findInDatabase(id);\n    if (user) {\n      this.cache.set(id, user);\n    }\n    return user;\n  }\n  \n  async save(entity: User): Promise<User> {\n    // Save to database\n    const saved = await this.saveToDatabase(entity);\n    this.cache.set(saved.id, saved);\n    return saved;\n  }\n  \n  async delete(id: number): Promise<void> {\n    this.cache.delete(id);\n    await this.deleteFromDatabase(id);\n  }\n  \n  cache(): void {\n    console.log(\"Cache warmed up\");\n  }\n  \n  invalidate(): void {\n    this.cache.clear();\n  }\n  \n  private async findInDatabase(id: number): Promise<User | null> {\n    // Database implementation\n    return null;\n  }\n  \n  private async saveToDatabase(entity: User): Promise<User> {\n    // Database implementation\n    return entity;\n  }\n  \n  private async deleteFromDatabase(id: number): Promise<void> {\n    // Database implementation\n  }\n}\n```\n\n**Intersection vs Union:**\n```typescript\n// Union: Value can be one OR the other\ntype StringOrNumber = string | number;\nlet unionVar: StringOrNumber = \"hello\"; // OK\nunionVar = 42; // OK\n\n// Intersection: Value must have properties of BOTH\ntype StringAndNumber = { str: string } & { num: number };\nlet intersectionVar: StringAndNumber = {\n  str: \"hello\",\n  num: 42\n};\n```\n\n**Practical Use Cases:**\n\n**1. Plugin Systems:**\n```typescript\ninterface Plugin {\n  name: string;\n  version: string;\n}\n\ninterface Loggable {\n  log(message: string): void;\n}\n\ninterface Configurable {\n  configure(config: any): void;\n}\n\ntype AdvancedPlugin = Plugin & Loggable & Configurable;\n```\n\n**2. API Response Enhancement:**\n```typescript\ninterface ApiResponse<T> {\n  data: T;\n  status: number;\n}\n\ninterface Paginated {\n  page: number;\n  total: number;\n  pageSize: number;\n}\n\ntype PaginatedResponse<T> = ApiResponse<T[]> & Paginated;\n```\n\n**3. Configuration Merging:**\n```typescript\ninterface DatabaseConfig {\n  host: string;\n  port: number;\n}\n\ninterface AuthConfig {\n  secret: string;\n  expiresIn: string;\n}\n\ntype AppConfig = DatabaseConfig & AuthConfig;\n```\n\n**Benefits of Intersection Types:**\n- **Composition**: Build complex types from simple ones\n- **Code Reuse**: Combine existing type definitions\n- **Mixin Pattern**: Add functionality to existing types\n- **Flexibility**: Create type-safe combinations\n- **Extensibility**: Enhance types without modification\n\n**When to Use Intersection Types:**\n- Combining multiple interfaces\n- Adding functionality to existing types\n- Creating mixins\n- Merging configuration objects\n- Enhancing API responses"
