    question: "What are optional properties?",
    idealAnswer: "**Optional properties** in TypeScript allow you to define object properties that may or may not be present. They're denoted using a question mark (`?`) after the property name.\n\n**Basic Syntax:**\n```typescript\ninterface InterfaceName {\n  requiredProperty: Type;\n  optionalProperty?: Type;\n}\n```\n\n**Simple Examples:**\n```typescript\ninterface User {\n  id: number;\n  name: string;\n  email?: string;    // Optional\n  phone?: string;    // Optional\n  age?: number;      // Optional\n}\n\n// All valid User objects\nconst user1: User = {\n  id: 1,\n  name: \"John\"\n};\n\nconst user2: User = {\n  id: 2,\n  name: \"Jane\",\n  email: \"jane@example.com\"\n};\n\nconst user3: User = {\n  id: 3,\n  name: \"Bob\",\n  email: \"bob@example.com\",\n  phone: \"123-456-7890\",\n  age: 30\n};\n```\n\n**Optional Properties in Functions:**\n```typescript\nfunction createUser(userData: User): User {\n  return {\n    id: userData.id,\n    name: userData.name,\n    email: userData.email || \"\",\n    phone: userData.phone || \"\",\n    age: userData.age || 0\n  };\n}\n\n// Usage\nconst user = createUser({\n  id: 1,\n  name: \"Alice\",\n  email: \"alice@example.com\"\n  // phone and age are optional\n});\n```\n\n**Optional Method Parameters:**\n```typescript\ninterface Greeter {\n  greet(name: string, punctuation?: string): void;\n}\n\nclass EnglishGreeter implements Greeter {\n  greet(name: string, punctuation?: string): void {\n    const punct = punctuation || \"!\";\n    console.log(`Hello, ${name}${punct}`);\n  }\n}\n\nconst greeter = new EnglishGreeter();\ngreeter.greet(\"World\");           // \"Hello, World!\"\ngreeter.greet(\"World\", \"!!!\");    // \"Hello, World!!!\"\n```\n\n**Optional Properties with Default Values:**\n```typescript\ninterface Config {\n  apiUrl: string;\n  timeout?: number;\n  retries?: number;\n  debug?: boolean;\n}\n\nclass ApiClient {\n  private config: Required<Config>;\n  \n  constructor(config: Config) {\n    this.config = {\n      timeout: 5000,     // Default value\n      retries: 3,       // Default value\n      debug: false,     // Default value\n      ...config\n    };\n  }\n  \n  makeRequest(): void {\n    console.log(`Timeout: ${this.config.timeout}ms`);\n    console.log(`Retries: ${this.config.retries}`);\n    console.log(`Debug: ${this.config.debug}`);\n  }\n}\n\nconst client = new ApiClient({\n  apiUrl: \"https://api.example.com\",\n  debug: true\n  // timeout and retries use defaults\n});\n```\n\n**Optional Properties and Type Narrowing:**\n```typescript\ninterface UserProfile {\n  id: number;\n  name: string;\n  bio?: string;\n  website?: string;\n}\n\nfunction displayProfile(profile: UserProfile): void {\n  console.log(`Name: ${profile.name}`);\n  \n  // Check if optional property exists\n  if (profile.bio) {\n    console.log(`Bio: ${profile.bio}`);\n  }\n  \n  if (profile.website) {\n    console.log(`Website: ${profile.website}`);\n  }\n  \n  // Using optional chaining\n  console.log(`Bio length: ${profile.bio?.length ?? 0}`);\n  console.log(`Website domain: ${profile.website?.split(\"//\")[1] ?? \"N/A\"}`);\n}\n```\n\n**Optional Properties in Classes:**\n```typescript\nclass Product {\n  constructor(\n    public id: number,\n    public name: string,\n    public description?: string,\n    public price?: number,\n    public category?: string\n  ) {}\n  \n  getDisplayInfo(): string {\n    let info = `${this.name} (ID: ${this.id})`;\n    \n    if (this.description) {\n      info += ` - ${this.description}`;\n    }\n    \n    if (this.price) {\n      info += ` - $${this.price}`;\n    }\n    \n    if (this.category) {\n      info += ` [${this.category}]`;\n    }\n    \n    return info;\n  }\n}\n```\n\n**Optional Properties with Utility Types:**\n```typescript\ninterface CompleteUser {\n  id: number;\n  name: string;\n  email: string;\n  phone: string;\n  address: string;\n  birthDate: Date;\n}\n\n// Make all properties optional\ntype PartialUser = Partial<CompleteUser>;\n\n// Make specific properties optional\ntype UserUpdate = Omit<CompleteUser, 'id'> & {\n  name?: string;\n  email?: string;\n  phone?: string;\n};\n\n// Function updates only provided fields\nfunction updateUser(id: number, updates: UserUpdate): CompleteUser {\n  // Implementation would merge updates with existing user\n  return {} as CompleteUser;\n}\n```\n\n**Optional Properties and Mapped Types:**\n```typescript\n// Create a type where all properties are optional\ntype Optionalize<T> = {\n  [K in keyof T]?: T[K];\n};\n\n// Create a type where specific properties are optional\ntype OptionalProperties<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;\n\ninterface Product {\n  id: number;\n  name: string;\n  price: number;\n  description: string;\n  category: string;\n}\n\ntype ProductUpdate = OptionalProperties<Product, 'description' | 'category'>;\n// { id: number; name: string; price: number; description?: string; category?: string; }\n```\n\n**Optional Properties in API Design:**\n```typescript\n// Query parameters with optional filters\ninterface QueryParams {\n  page?: number;\n  limit?: number;\n  sortBy?: string;\n  sortOrder?: 'asc' | 'desc';\n  filter?: string;\n}\n\nfunction buildUrl(baseUrl: string, params: QueryParams): string {\n  const url = new URL(baseUrl);\n  \n  Object.entries(params).forEach(([key, value]) => {\n    if (value !== undefined) {\n      url.searchParams.set(key, String(value));\n    }\n  });\n  \n  return url.toString();\n}\n\n// Usage\nconst url = buildUrl('https://api.example.com/users', {\n  page: 1,\n  limit: 20,\n  sortBy: 'name'\n  // sortOrder and filter are optional\n});\n```\n\n**Benefits of Optional Properties:**\n- **Flexibility**: Objects can have varying shapes\n- **Backward Compatibility**: Add new properties without breaking existing code\n- **API Design**: Create flexible function parameters\n- **Configuration**: Optional settings with sensible defaults\n- **Partial Updates**: Update only specific fields\n\n**When to Use Optional Properties:**\n- When properties are truly optional\n- For backward compatibility\n- In configuration objects\n- For API parameters and responses\n- When creating partial update types"
